_VALID_MODES = ("all", "remote", "hybrid", "office")


def submit(owner, enqueue, mode="all"):
    if mode not in _VALID_MODES:
        raise ValueError(
            "invalid mode {!r}: expected one of {}".format(mode, ", ".join(_VALID_MODES))
